<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>نقش‌ها</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}.panel{background:#0a1b2b;border:1px solid #1b354b;border-radius:16px;padding:20px;max-width:1100px;margin:auto}.role{border:1px solid #1b354b;padding:15px;border-radius:12px;margin:10px 0}input{padding:8px;background:#081522;border:1px solid #29465e;color:white;border-radius:7px}.checks{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.checks label{background:#10283c;padding:6px;border-radius:7px}button{padding:8px 12px;background:#123b4d;color:#6ee7d0;border:0;border-radius:7px;margin:3px}</style><div class="panel"><h1>نقش‌ها و Permissionها</h1>@if(session('success'))<p>{{ session('success') }}</p>@endif<form method="POST" action="{{ route('roles.store') }}">@csrf<input name="name" placeholder="نام نقش" required><input name="slug" placeholder="slug" required><input name="description" placeholder="توضیح"><div class="checks">@foreach($permissions as $p)<label><input type="checkbox" name="permissions[]" value="{{ $p->id }}"> {{ $p->name }}</label>@endforeach</div><button>ایجاد نقش</button></form>@foreach($roles as $role)<div class="role"><b>{{ $role->name }}</b> — {{ $role->slug }} @if(!$role->is_system)<form method="POST" action="{{ route('roles.update',$role) }}">@csrf @method('PUT')<p><input name="name" value="{{ $role->name }}" required><input name="slug" value="{{ $role->slug }}" required></p><div class="checks">@foreach($permissions as $p)<label><input type="checkbox" name="permissions[]" value="{{ $p->id }}" @checked($role->permissions->contains($p->id))> {{ $p->name }}</label>@endforeach</div><button>ذخیره نقش</button></form><form method="POST" action="{{ route('roles.destroy',$role) }}">@csrf @method('DELETE')<button>حذف نقش</button></form>@else<p>{{ $role->permissions->pluck('name')->join('، ') }}</p>@endif</div>@endforeach</div></html>